//! Weight functions for pallet-subnet-registry. `()` holds the estimates used until the runtime ships
//! benchmarked weights (runtime/src/weights/, generated by scripts/run-benchmarks.sh).
#![allow(unused_parens, unused_imports)]

use polkadot_sdk::frame_support::weights::{constants::RocksDbWeight, Weight};

pub trait WeightInfo {
    fn register_subnet() -> Weight;
    fn deregister_subnet(n: u32) -> Weight;
    fn register_neuron() -> Weight;
    fn set_endpoint() -> Weight;
    fn end_bootstrap() -> Weight;
    fn declare_tier() -> Weight;
    fn set_tier() -> Weight;
    fn enable_phase2() -> Weight;
}

impl WeightInfo for () {
    fn register_subnet() -> Weight {
        RocksDbWeight::get().reads_writes(6, 5)
    }
    fn deregister_subnet(n: u32) -> Weight {
        RocksDbWeight::get().reads_writes(3, 3 + 4 * n as u64)
    }
    fn register_neuron() -> Weight {
        RocksDbWeight::get().reads_writes(4, 4)
    }
    fn set_endpoint() -> Weight {
        RocksDbWeight::get().reads_writes(1, 1)
    }
    fn end_bootstrap() -> Weight {
        RocksDbWeight::get().reads_writes(2, 1)
    }
    fn declare_tier() -> Weight {
        RocksDbWeight::get().reads_writes(2, 1)
    }
    fn set_tier() -> Weight {
        RocksDbWeight::get().writes(1)
    }
    fn enable_phase2() -> Weight {
        RocksDbWeight::get().writes(1)
    }
}
